"use client";

import { useQuery } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";

// ── Types ──────────────────────────────────────────────────────────────

export interface Testimonial {
  name: string;
  role: string;
  company: string;
  quote: string;
  avatar_initials: string;
  rating: number;
}

export interface TrustBadge {
  icon: "lock" | "shield" | "check-circle";
  label: string;
}

export interface SignupBenefit {
  highlight: string;
  text: string;
}

export interface AuthPageConfig {
  hero_headline: string;
  hero_description: string;
  logo_url: string | null;
  social_proof_count: string;
  social_proof_label: string;
  testimonials: Testimonial[];
  trust_badges: TrustBadge[];
  signup_benefits: SignupBenefit[];
  signup_headline: string;
  signup_social_proof_count: string;
  signup_social_proof_label: string;
  google_auth_enabled: boolean;
  microsoft_auth_enabled: boolean;
  magic_link_enabled: boolean;
  signin_heading: string;
  signin_subheading: string;
  signup_heading: string;
  signup_subheading: string;
}

// ── Defaults (used before DB config loads or if table doesn't exist) ──

const DEFAULTS: AuthPageConfig = {
  hero_headline: "Hire smarter.\nRank better.",
  hero_description:
    "AI-powered recruitment that helps you find the best talent faster. Join 500+ companies already transforming their hiring.",
  logo_url: null,
  social_proof_count: "500+",
  social_proof_label: "hiring teams",
  testimonials: [
    {
      name: "Sarah Chen",
      role: "VP of People",
      company: "TechCorp",
      quote:
        "Rankora cut our time-to-hire by 40%. The AI ranking saves our team 15+ hours per week on resume screening.",
      avatar_initials: "SC",
      rating: 5,
    },
  ],
  trust_badges: [
    { icon: "lock", label: "256-bit SSL" },
    { icon: "shield", label: "SOC 2 Compliant" },
    { icon: "check-circle", label: "GDPR Ready" },
  ],
  signup_benefits: [
    {
      highlight: "No credit card required",
      text: "free trial with full access to all features",
    },
    {
      highlight: "AI resume ranking",
      text: "screen 100 resumes in seconds, not hours",
    },
    {
      highlight: "Team collaboration",
      text: "invite your hiring team and start working together",
    },
    {
      highlight: "Cancel anytime",
      text: "no lock-in, no hidden fees, ever",
    },
  ],
  signup_headline: "Start hiring smarter\nin under 2 minutes",
  signup_social_proof_count: "2,400+",
  signup_social_proof_label: "recruiters signed up this month",
  google_auth_enabled: true,
  microsoft_auth_enabled: true,
  magic_link_enabled: true,
  signin_heading: "Welcome back",
  signin_subheading: "Sign in to continue to your dashboard",
  signup_heading: "Create your account",
  signup_subheading: "Just your email to start",
};

// ── Fetcher ────────────────────────────────────────────────────────────

async function fetchAuthPageConfig(): Promise<AuthPageConfig> {
  try {
    const { data, error } = await supabase
      .from("auth_page_config")
      .select("*")
      .limit(1)
      .maybeSingle();

    if (error || !data) return DEFAULTS;

    return {
      hero_headline: data.hero_headline ?? DEFAULTS.hero_headline,
      hero_description: data.hero_description ?? DEFAULTS.hero_description,
      logo_url: data.logo_url ?? null,
      social_proof_count:
        data.social_proof_count ?? DEFAULTS.social_proof_count,
      social_proof_label:
        data.social_proof_label ?? DEFAULTS.social_proof_label,
      testimonials: Array.isArray(data.testimonials_json)
        ? (data.testimonials_json as Testimonial[])
        : DEFAULTS.testimonials,
      trust_badges: Array.isArray(data.trust_badges_json)
        ? (data.trust_badges_json as TrustBadge[])
        : DEFAULTS.trust_badges,
      signup_benefits: Array.isArray(data.signup_benefits_json)
        ? (data.signup_benefits_json as SignupBenefit[])
        : DEFAULTS.signup_benefits,
      signup_headline: data.signup_headline ?? DEFAULTS.signup_headline,
      signup_social_proof_count:
        data.signup_social_proof_count ?? DEFAULTS.signup_social_proof_count,
      signup_social_proof_label:
        data.signup_social_proof_label ?? DEFAULTS.signup_social_proof_label,
      google_auth_enabled: data.google_auth_enabled ?? true,
      microsoft_auth_enabled: data.microsoft_auth_enabled ?? true,
      magic_link_enabled: data.magic_link_enabled ?? true,
      signin_heading: data.signin_heading ?? DEFAULTS.signin_heading,
      signin_subheading: data.signin_subheading ?? DEFAULTS.signin_subheading,
      signup_heading: data.signup_heading ?? DEFAULTS.signup_heading,
      signup_subheading: data.signup_subheading ?? DEFAULTS.signup_subheading,
    };
  } catch {
    // Table may not exist yet — fall back to defaults
    return DEFAULTS;
  }
}

// ── Hook ───────────────────────────────────────────────────────────────

export function useAuthPageConfig() {
  const { data, isLoading } = useQuery({
    queryKey: ["auth-page-config"],
    queryFn: fetchAuthPageConfig,
    staleTime: 5 * 60 * 1000, // 5 minutes
    gcTime: 30 * 60 * 1000, // 30 minutes
    retry: 1,
  });

  return {
    config: data ?? DEFAULTS,
    isLoading,
  };
}

