          className="flex flex-1 items-center justify-center gap-2.5 rounded-[10px] border border-border bg-white px-4 py-3 text-[13px] font-medium text-gray-600 transition-all hover:-translate-y-px hover:border-gray-300 hover:bg-gray-50 active:translate-y-0 disabled:opacity-50 dark:bg-card dark:text-gray-300 dark:hover:bg-muted"
        >
          {loadingProvider === "azure" ? (
            <Loader2 className="h-4 w-4 animate-spin" />
          ) : (
            <MicrosoftIcon />
          )}
          {showMicrosoft && !showGoogle
            ? `${label} Microsoft`
            : "Microsoft"}
        </button>
      )}
    </div>
  );
}

