"use client";

import { useState } from "react";
import { supabase } from "@/integrations/supabase/client";
import { Input } from "@/components/ui/input";
import { toast } from "sonner";
import { Loader2 } from "lucide-react";
import type { AuthPageConfig } from "@/hooks/useAuthPageConfig";
import { SocialAuthButtons } from "./SocialAuthButtons";
import { Divider } from "./Divider";
import { TrustBadges } from "./TrustBadges";

interface SignInFormProps {
  config: AuthPageConfig;
  onSuccess?: () => void;
  onSwitchToSignUp: () => void;
  onForgotPassword: () => void;
}

export function SignInForm({
  config,
  onSuccess,
  onSwitchToSignUp,
  onForgotPassword,
}: SignInFormProps) {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [loading, setLoading] = useState(false);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    try {
      const { error } = await supabase.auth.signInWithPassword({
        email,
        password,
      });
      if (error) {
        toast.error(error.message);
      } else {
        toast.success("Signed in successfully");
        onSuccess?.();
      }
    } catch {
      toast.error("An unexpected error occurred. Please try again.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="flex w-full flex-col justify-center bg-background px-8 py-12 sm:px-12 lg:px-14">
      <div className="mx-auto w-full max-w-[400px]">
        {/* Mobile logo — visible only below md */}
        <div className="mb-8 flex items-center gap-2.5 md:hidden">
          <div className="flex h-8 w-8 items-center justify-center rounded-lg bg-gradient-to-br from-indigo-500 to-indigo-400 text-sm font-extrabold text-white">
            R
          </div>
          <span className="text-xl font-bold tracking-tight">Rankora</span>
        </div>

        {/* Header */}
        <div className="mb-7">
          <h2 className="text-[26px] font-bold tracking-tight text-foreground">
            {config.signin_heading}
          </h2>
          <p className="mt-1.5 text-[14px] text-muted-foreground">
            {config.signin_subheading}
          </p>
        </div>

        {/* SSO */}
        <SocialAuthButtons
          googleEnabled={config.google_auth_enabled}
          microsoftEnabled={config.microsoft_auth_enabled}
          mode="signin"
          disabled={loading}
        />

        {(config.google_auth_enabled || config.microsoft_auth_enabled) && (
          <div className="my-5">
            <Divider />
          </div>
        )}

        {/* Email / Password form */}
        <form onSubmit={handleSubmit} className="space-y-4">
          <div className="space-y-1.5">
            <label
              htmlFor="signin-email"
              className="text-[13px] font-medium text-foreground/80"
            >
              Email
            </label>
            <Input
              id="signin-email"
              type="email"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              placeholder="name@company.com"
              autoComplete="email"
              required
              className="h-[46px] rounded-[10px] border-border bg-background px-3.5 text-[14px] placeholder:text-muted-foreground/40 focus-visible:border-indigo-500 focus-visible:ring-indigo-500/10"
            />
          </div>

          <div className="space-y-1.5">
            <label
              htmlFor="signin-password"
              className="text-[13px] font-medium text-foreground/80"
            >
              Password
            </label>
            <Input
              id="signin-password"
              type="password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              placeholder="Enter your password"
              autoComplete="current-password"
              required
              className="h-[46px] rounded-[10px] border-border bg-background px-3.5 text-[14px] placeholder:text-muted-foreground/40 focus-visible:border-indigo-500 focus-visible:ring-indigo-500/10"
            />
          </div>

          {/* Remember me + Forgot */}
          <div className="flex items-center justify-between">
            <label className="flex cursor-pointer items-center gap-2 text-[13px] text-muted-foreground">
              <input
                type="checkbox"
                defaultChecked
                className="h-4 w-4 rounded accent-indigo-500"
              />
              Remember me
            </label>
            <button
              type="button"
              onClick={onForgotPassword}
              className="text-[13px] font-medium text-indigo-500 hover:underline"
            >
              Forgot password?
            </button>
          </div>

          {/* Submit */}
          <button
            type="submit"
            disabled={loading}
            className="relative mt-2 flex w-full items-center justify-center rounded-[10px] bg-[#1a1a2e] px-4 py-3.5 text-[14px] font-semibold text-white transition-all hover:-translate-y-px hover:bg-[#2d2b55] hover:shadow-lg active:translate-y-0 disabled:opacity-50 dark:bg-indigo-600 dark:hover:bg-indigo-500"
          >
            {loading && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
            Sign in
          </button>
        </form>

        {/* Switch to signup */}
        <p className="mt-5 text-center text-[13px] text-muted-foreground">
          Don&apos;t have an account?{" "}
          <button
            type="button"
            onClick={onSwitchToSignUp}
            className="font-semibold text-indigo-500 hover:underline"
          >
            Start free trial &rarr;
          </button>
        </p>

        {/* Trust badges */}
        <div className="mt-6">
          <TrustBadges badges={config.trust_badges} />
        </div>
      </div>
    </div>
  );
}

