input.content:
"use client";

import { useState } from "react";
import { supabase } from "@/integrations/supabase/client";
import { Input } from "@/components/ui/input";
import { toast } from "sonner";
import { Loader2 } from "lucide-react";
import type { AuthPageConfig } from "@/hooks/useAuthPageConfig";
import { SocialAuthButtons } from "./SocialAuthButtons";
import { Divider } from "./Divider";
import { TrustBadges } from "./TrustBadges";

interface SignUpFormProps {
  config: AuthPageConfig;
  onSuccess?: () => void;
  onSwitchToSignIn: () => void;
}

type Step = 1 | 2 | 3;

export function SignUpForm({
  config,
  onSuccess,
  onSwitchToSignIn,
}: SignUpFormProps) {
  const [step, setStep] = useState<Step>(1);
  const [email, setEmail] = useState("");
  const [fullName, setFullName] = useState("");
  const [password, setPassword] = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");
  const [loading, setLoading] = useState(false);

  const handleStep1 = (e: React.FormEvent) => {
    e.preventDefault();
    if (!email) return;
    setStep(2);
  };

  const handleStep2 = (e: React.FormEvent) => {
    e.preventDefault();
    if (!fullName) return;
    setStep(3);
  };

  const handleStep3 = async (e: React.FormEvent) => {
    e.preventDefault();
    if (password !== confirmPassword) {
      toast.error("Passwords do not match");
      return;
    }
    if (password.length < 6) {
      toast.error("Password must be at least 6 characters");
      return;
    }

    setLoading(true);
    try {
      const { error } = await supabase.auth.signUp({
        email,
        password,
        options: {
          emailRedirectTo: window.location.origin,
          data: { full_name: fullName },
        },
      });
      if (error) {
        toast.error(error.message);
      } else {
        toast.success("Check your email to confirm your account!");
        onSuccess?.();
      }
    } catch {
      toast.error("An unexpected error occurred. Please try again.");
    } finally {
      setLoading(false);
    }
  };

  const stepLabel = `Step ${step} of 3`;

  return (
    <div className="flex w-full flex-col justify-center bg-background px-8 py-12 sm:px-12 lg:px-14">
      <div className="mx-auto w-full max-w-[400px]">
        {/* Mobile logo */}
        <div className="mb-8 flex items-center gap-2.5 md:hidden">
          <div className="flex h-8 w-8 items-center justify-center rounded-lg bg-gradient-to-br from-indigo-500 to-indigo-400 text-sm font-extrabold text-white">
            R
          </div>
          <span className="text-xl font-bold tracking-tight">Rankora</span>
        </div>

        {/* Step indicator */}
        <div className="mb-6 flex items-center gap-2">
          {([1, 2, 3] as const).map((s) => (
            <div
              key={s}
              className={`h-2 rounded-full transition-all duration-300 ${
                s === step
                  ? "w-6 bg-indigo-500"
                  : s < step
                    ? "w-2 bg-green-500"
                    : "w-2 bg-border"
              }`}
            />
          ))}
        </div>

        {/* Header */}
        <div className="mb-7">
          <h2 className="text-[26px] font-bold tracking-tight text-foreground">
            {config.signup_heading}
          </h2>
          <p className="mt-1.5 text-[14px] text-muted-foreground">
            {stepLabel} — {stepSubheading(step)}
          </p>
        </div>

        {/* Step 1: Email only */}
        {step === 1 && (
          <>
            <SocialAuthButtons
              googleEnabled={config.google_auth_enabled}
              microsoftEnabled={config.microsoft_auth_enabled}
              mode="signup"
              disabled={loading}
            />

            {(config.google_auth_enabled ||
              config.microsoft_auth_enabled) && (
              <div className="my-5">
                <Divider />
              </div>
            )}

            <form onSubmit={handleStep1} className="space-y-4">
              <div className="space-y-1.5">
                <label
                  htmlFor="signup-email"
                  className="text-[13px] font-medium text-foreground/80"
                >
                  Work email
                </label>
                <Input
                  id="signup-email"
                  type="email"
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                  placeholder="name@company.com"
                  autoComplete="email"
                  autoFocus
                  required
                  className="h-[46px] rounded-[10px] border-border bg-background px-3.5 text-[14px] placeholder:text-muted-foreground/40 focus-visible:border-indigo-500 focus-visible:ring-indigo-500/10"
                />
              </div>

              <button
                type="submit"
                className="flex w-full items-center justify-center rounded-[10px] bg-indigo-500 px-4 py-3.5 text-[14px] font-semibold text-white transition-all hover:-translate-y-px hover:bg-indigo-600 hover:shadow-lg active:translate-y-0"
              >
                Continue &rarr;
              </button>
            </form>
          </>
        )}

        {/* Step 2: Full name */}
        {step === 2 && (
          <form onSubmit={handleStep2} className="space-y-4">
            <div className="space-y-1.5">
              <label
                htmlFor="signup-name"
                className="text-[13px] font-medium text-foreground/80"
              >
                Full name
              </label>
              <Input
                id="signup-name"
                type="text"
                value={fullName}
                onChange={(e) => setFullName(e.target.value)}
                placeholder="Jane Smith"
                autoComplete="name"
                autoFocus
                required
                className="h-[46px] rounded-[10px] border-border bg-background px-3.5 text-[14px] placeholder:text-muted-foreground/40 focus-visible:border-indigo-500 focus-visible:ring-indigo-500/10"
              />
            </div>

            <div className="flex gap-3">
              <button
                type="button"
                onClick={() => setStep(1)}
                className="flex-1 rounded-[10px] border border-border px-4 py-3 text-[14px] font-medium text-foreground transition-colors hover:bg-muted"
              >
                Back
              </button>
              <button
                type="submit"
                className="flex flex-[2] items-center justify-center rounded-[10px] bg-indigo-500 px-4 py-3 text-[14px] font-semibold text-white transition-all hover:-translate-y-px hover:bg-indigo-600 hover:shadow-lg active:translate-y-0"
              >
                Continue &rarr;
              </button>
            </div>
          </form>
        )}

        {/* Step 3: Password */}
        {step === 3 && (
          <form onSubmit={handleStep3} className="space-y-4">
            <div className="space-y-1.5">
              <label
                htmlFor="signup-password"
                className="text-[13px] font-medium text-foreground/80"
              >
                Password
              </label>
              <Input
                id="signup-password"
                type="password"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                placeholder="Min 6 characters"
                autoComplete="new-password"
                autoFocus
                required
                minLength={6}
                className="h-[46px] rounded-[10px] border-border bg-background px-3.5 text-[14px] placeholder:text-muted-foreground/40 focus-visible:border-indigo-500 focus-visible:ring-indigo-500/10"
              />
              <p className="text-xs text-muted-foreground">
                At least 6 characters required
              </p>
            </div>

            <div className="space-y-1.5">
              <label
                htmlFor="signup-confirm-password"
                className="text-[13px] font-medium text-foreground/80"
              >
                Confirm password
              </label>
              <Input
                id="signup-confirm-password"
                type="password"
                value={confirmPassword}
                onChange={(e) => setConfirmPassword(e.target.value)}
                placeholder="Repeat password"
                autoComplete="new-password"
                required
                minLength={6}
                className="h-[46px] rounded-[10px] border-border bg-background px-3.5 text-[14px] placeholder:text-muted-foreground/40 focus-visible:border-indigo-500 focus-visible:ring-indigo-500/10"
              />
              {confirmPassword && password !== confirmPassword && (
                <p className="text-xs text-destructive">
                  Passwords do not match
                </p>
              )}
            </div>

            <div className="flex gap-3">
              <button
                type="button"
                onClick={() => setStep(2)}
                className="flex-1 rounded-[10px] border border-border px-4 py-3 text-[14px] font-medium text-foreground transition-colors hover:bg-muted"
              >
                Back
              </button>
              <button
                type="submit"
                disabled={
                  loading ||
                  (!!confirmPassword && password !== confirmPassword)
                }
                className="flex flex-[2] items-center justify-center rounded-[10px] bg-[#1a1a2e] px-4 py-3 text-[14px] font-semibold text-white transition-all hover:-translate-y-px hover:bg-[#2d2b55] hover:shadow-lg active:translate-y-0 disabled:opacity-50 dark:bg-indigo-600 dark:hover:bg-indigo-500"
              >
                {loading && (
                  <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                )}
